        "Az élesztőt a langyos tejben egy kiskanál cukorral felfuttatod. A lisztet a 10 dkg cukorral, a sóval és a narancshéjjal összekevered, hozzáadod a 3 tojást, a narancslevet és az élesztős tejet, és 10 percig dagasztod. Fokozatosan belegyúrod a puha vajat, amíg a tészta sima, fényes és elválik a tál falától. Letakarva 2 órát keleszted.",
